import{_ as t,c as a,o as s,a3 as r}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Recruitment setup","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/setup/index.md","filePath":"master/human-resources/recruitment/setup/index.md","lastUpdated":1792041590000}'),o={name:"master/human-resources/recruitment/setup/index.md"};function i(d,e,n,h,l,p){return s(),a("div",null,e[0]||(e[0]=[r('<h1 id="recruitment-setup" tabindex="-1">Recruitment setup <a class="header-anchor" href="#recruitment-setup" aria-label="Permalink to &quot;Recruitment setup&quot;">​</a></h1><p>Setup holds the lists that feed the applicant form and the hiring flow. You set them once and then pick from them while you work. Good setup saves typing and keeps your reports consistent.</p><blockquote><p><strong>In simple words:</strong> Setup is where you define stages, reasons, tags and other choices that applicants use.</p></blockquote><p>Open <code>Recruitments → Configuration</code>. The menu on the left lists every setup page. Start with the four pages written for Recruitment below.</p><h2 id="pages-written-for-recruitment" tabindex="-1">Pages written for Recruitment <a class="header-anchor" href="#pages-written-for-recruitment" aria-label="Permalink to &quot;Pages written for Recruitment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it holds</th><th>Used on</th></tr></thead><tbody><tr><td><a href="./stages.html">Stages</a></td><td>The steps an applicant passes through, with state labels and a hired flag</td><td>The stage bar of an applicant</td></tr><tr><td><a href="./refuse-reasons.html">Refuse reasons</a></td><td>Why an application is refused, with the email template</td><td>The <strong>Refuse</strong> window</td></tr><tr><td><a href="./tags-degrees.html">Tags and degrees</a></td><td>Coloured labels and education levels</td><td>The applicant and candidate forms</td></tr><tr><td><a href="./sources-and-mediums.html">Sources and mediums</a></td><td>Where the applicant came from</td><td>The <strong>Source &amp; Medium</strong> section</td></tr></tbody></table><h2 id="pages-shared-with-employees" tabindex="-1">Pages shared with Employees <a class="header-anchor" href="#pages-shared-with-employees" aria-label="Permalink to &quot;Pages shared with Employees&quot;">​</a></h2><p>These records live in the same Configuration menu. Other apps use them too, so some are explained in the Employees guide.</p><table tabindex="0"><thead><tr><th>Page</th><th>Why Recruitment needs it</th></tr></thead><tbody><tr><td><a href="./../job-positions/job-positions.html">Job positions</a></td><td>The roles you hire for</td></tr><tr><td><a href="./../../employees/departments/departments.html">Departments</a></td><td>The department of each role</td></tr><tr><td><a href="./../../employees/setup/employment-types.html">Employment types</a></td><td>Full-Time, Intern and others on a role</td></tr><tr><td><a href="./../../employees/setup/skill-types.html">Skill types</a></td><td>The skills of candidates and roles</td></tr><tr><td><a href="./../../employees/setup/activity-plans.html">Activity plans</a></td><td>Task checklists you can start from an applicant</td></tr></tbody></table><h2 id="what-to-set-up-first" tabindex="-1">What to set up first <a class="header-anchor" href="#what-to-set-up-first" aria-label="Permalink to &quot;What to set up first&quot;">​</a></h2><ol><li>Check the <a href="./stages.html">stages</a>. The sample stages work for most teams.</li><li>Check the <a href="./refuse-reasons.html">refuse reasons</a>.</li><li>Add the <a href="./tags-degrees.html">tags and degrees</a> you use.</li><li>Add the <a href="./sources-and-mediums.html">sources and mediums</a> you track.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Recruitment has no separate settings page. Everything is managed from this menu.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../get-started/first-steps.html">Get started: first steps</a></li><li><a href="./../applicants/add-applicant.html">Add an applicant</a></li><li><a href="./../">Recruitment overview</a></li></ul>',14)]))}const c=t(o,[["render",i]]);export{u as __pageData,c as default};
